import { defineStore } from 'pinia';
import { supplierGroupApiService } from 'src/services';

export interface PaginationMetadata {
  total_results: number;
  skip: number;
  limit: number;
}

export const useSupplierGroupStore = defineStore('supplier_group_store', {
  state: () => ({
    display_data: [] as any[],
    loading: true,
    pagination: {
      total_results: 0,
      skip: 0,
      limit: 100,
    } as PaginationMetadata,
  }),
  actions: {
    async getAll(skip = 0, limit = 100, sortBy?: string, order?: string, keyword?: string) {
      const response = await supplierGroupApiService.list(skip, limit, sortBy, order, keyword);
      if (response) {
        this.display_data = response?.data || [];
        if (response?.metadata) {
          this.pagination = {
            total_results: response.metadata.total_results || 0,
            skip: response.metadata.skip || 0,
            limit: response.metadata.limit || 100,
          };
        }
      }
    },
  },
});
