<template>
  <q-card style="width: 600px">
    <q-form @submit="onSubmit">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title>
          <span class="text-weight-bold"> {{ $t('create_new_group') }} </span>
        </q-toolbar-title>
        <q-btn flat round dense icon="close" class="text-white" v-close-popup />
      </q-toolbar>

      <q-card-section class="q-mt-md">
        <f-input
          v-model="groupApiName"
          :label="$t('group_api_name')"
          class="col-12"
          lazy-rules
          :rules="[
            (val: any) =>
              (val && val.length > 0) || 'Please input group api name',
          ]"
        />
        <f-input
          v-model="groupName"
          :label="$t('group_name')"
          class="col-12 q-mt-sm"
          lazy-rules
          :rules="[
            (val: any) => (val && val.length > 0) || 'Please input group name',
          ]"
        />
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn type="submit" class="q-mr-sm" :label="$t('save')" />
      </q-card-actions>
    </q-form>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import { supplierGroupApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions';
import { useSupplierGroupStore } from './store/supplier.store';
export default defineComponent({
  el: '#app',
    props: {
    getDisplay: {
      type: Function,
      required: true,
    },
    getLoading: {
      type: Function,
      required: true,
    },
  },
  components: {},
  setup() {
    const supplier_group_store = useSupplierGroupStore();
    const { getAll } = supplier_group_store;
    return {
      groupApiName: ref(''),
      groupName: ref(''),
      supplier_group_store,
      getAll,
    };
  },
  methods: {
    async onSubmit() {
      try {
        this.getDisplay(false);
        this.getLoading(true);

        const formData = new FormData();
        formData.append('group_name', this.groupApiName);
        formData.append('title', this.groupName);

        const result = await supplierGroupApiService.create(formData);
        if (result.success === false) {
          notify.error(result?.message);
        } else {
          await this.supplier_group_store.getAll();
          notify.success(this.$t('supplier_group_created_successfully'));
        }
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err);
        notify.error(msg);
      } finally {
        this.getLoading(false);
      }
    },
  },
});
</script>
