<template>
  <div class="full-width">
    <DocBitsTable
      :rows="display_data || []"
      :columns="columns"
      :loading="loading"
      row-key="id"
      table-id="supplier_group_table"
      :features="{
        sorting: true,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: true,
        resizable: false,
        pagination: true,
        columnReorder: false,
        columnSettings: false,
        stickyFirstColumn: false,
        stickyLastColumn: true,
      }"
      :row-actions="rowActions"
      :pagination="paginationState"
      :rows-per-page-options="[10, 20, 25, 50]"
      pagination-label="records_per_page"
      no-data-label="no_record_found"
      table-class="supplier-group-table-height"
      flat-style
      @row-action="handleRowAction"
      @update:pagination="handlePaginationChange"
      @update:sorting="handleSort"
    >
      <!-- Group API Name column -->
      <template #body-cell-group_api_name="{ row }">
        {{ row.group_name }}
      </template>

      <!-- Group Name column -->
      <template #body-cell-group_name="{ row }">
        {{ row.title }}
      </template>
    </DocBitsTable>
  </div>

  <q-dialog v-model="display_edit_dialog">
    <Edit :getData="getData" :getDisplay="DisplayDialog"></Edit>
  </q-dialog>

  <!-- delete dialog -->
  <q-dialog v-model="confirm_delete" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" />
      </q-card-section>
      <q-card-section class="row items-center">
        <span class="q-ml-sm">{{ $t('msg_delete') }}</span>
      </q-card-section>
      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn
          appearance="negative"
          :label="$t('delete')"
          v-close-popup
          @click="handleDelete"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>

  <Loader />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, computed, watch } from 'vue';
import { ApiExceptions } from 'src/exceptions';
import { useSupplierGroupStore } from './store/supplier.store';
import { storeToRefs } from 'pinia';
import Edit from './Edit.vue';
import { supplierGroupApiService } from 'src/services';
import { useTranslate } from '@tolgee/vue';
import { DocBitsTable } from 'src/components/Table';
import Loader from 'src/components/Loader.vue';
import type {
  UnifiedTableColumn,
  RowActionItem,
  RowActionPayload,
  PaginationChangePayload,
  TablePaginationState,
  SortEventPayload,
} from 'src/components/Table';

export default defineComponent({
  name: 'SupplierGroupList',
  components: {
    Edit,
    DocBitsTable,
    Loader,
  },
  props: {
    search: {
      type: String,
      default: '',
    },
  },
  mounted() {
    this.init();
  },
  data() {
    return {
      display_edit_dialog: false,
      confirm_delete: false,
      supplierData: null as any,
      id: '',
      currentPage: 1,
      rowsPerPage: 25,
      sortBy: null as string | null,
      descending: false,
    };
  },
  watch: {
    search() {
      this.currentPage = 1;
      this.getSupplierList();
    },
  },
  setup() {
    const supplier_group_store = useSupplierGroupStore();
    const { display_data, loading, pagination } = storeToRefs(supplier_group_store);
    const { getAll } = supplier_group_store;
    const { t } = useTranslate();

    // Column definitions for DocBitsTable
    const columns = computed<UnifiedTableColumn[]>(() => [
      {
        name: 'group_api_name',
        label: t.value('group_api_name'),
        field: 'group_name',
        sortable: true,
        align: 'left',
      },
      {
        name: 'group_name',
        label: t.value('group_name'),
        field: 'title',
        sortable: true,
        align: 'left',
      },
    ]);

    // Row actions for edit and delete
    const rowActions: RowActionItem[] = [
      {
        key: 'edit',
        label: 'edit',
        icon: 'edit',
        color: 'primary',
      },
      {
        key: 'delete',
        label: 'delete',
        icon: 'delete',
        color: 'negative',
        separator: true,
      },
    ];

    return {
      supplier_group_store,
      getAll,
      display_data,
      loading,
      pagination,
      t,
      columns,
      rowActions,
    };
  },
  computed: {
    paginationState(): TablePaginationState {
      return {
        page: this.currentPage,
        rowsPerPage: this.rowsPerPage,
        rowsNumber: this.pagination?.total_results || 0,
        sortBy: this.sortBy,
        descending: this.descending,
      };
    },
  },
  methods: {
    init() {
      this.getSupplierList();
    },
    async getSupplierList() {
      try {
        this.loading = true;
        const skip = (this.currentPage - 1) * this.rowsPerPage;

        // Map column names to API field names
        let sortBy: string | undefined;
        if (this.sortBy) {
          const fieldMap: Record<string, string> = {
            'group_api_name': 'group_name',
            'group_name': 'title',
          };
          sortBy = fieldMap[this.sortBy] || this.sortBy;
        }
        const order = this.sortBy ? (this.descending ? 'desc' : 'asc') : undefined;

        const keyword = this.search.trim() || undefined;
        await this.supplier_group_store.getAll(skip, this.rowsPerPage, sortBy, order, keyword);
      } catch (e: any) {
        logError(e);
      } finally {
        this.loading = false;
      }
    },
    handlePaginationChange(payload: PaginationChangePayload) {
      this.currentPage = payload.page;
      this.rowsPerPage = payload.rowsPerPage;
      this.getSupplierList();
    },
    handleSort(payload: SortEventPayload) {
      this.sortBy = payload.column;
      this.descending = payload.direction === 'desc';
      this.currentPage = 1;
      this.getSupplierList();
    },
    handleRowAction(payload: RowActionPayload) {
      const row = payload.row;
      if (payload.action === 'edit') {
        this.openFormEdit(row);
      } else if (payload.action === 'delete') {
        this.openFormDelete(row.id);
      }
    },
    openFormEdit(data: any) {
      this.display_edit_dialog = true;
      this.supplierData = data;
    },
    getData() {
      return this.supplierData;
    },
    openFormDelete(id: string) {
      this.confirm_delete = true;
      this.id = id;
    },
    async handleDelete() {
      try {
        this.loading = true;
        const response = await supplierGroupApiService.delete(this.id);
        if (response.success === true) {
          // Reload current page after delete (preserves sort state)
          await this.getSupplierList();
          notify.success(this.$t('supplier_group_deleted_successfully'));
        }
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err);
        notify.error(msg);
      } finally {
        this.loading = false;
      }
    },
    DisplayDialog(value: boolean) {
      this.display_edit_dialog = value;
    },
  },
});
</script>

<style lang="scss" scoped>
:deep(.supplier-group-table-height) {
  height: calc(100vh - 215px) !important;
}
</style>
