<template>
  <div class="container">
    <div class="row mt-10 mb-25 justify-between">
      <div class="col-sm-6 col-md-6 col-lg-6">
        <q-input
          v-model="searchBy"
          dense
          :class="searchBy.length === 0 ? 'search-in-active' : 'search-active'"
          :placeholder="$t('search_supplier_group')"
          outlined
          @update:model-value="updateSearchValue"
          @keyup.enter="searchSupplierGroup"
        >
          <template v-slot:append>
            <q-icon
              flat
              dense
              class="cursor-pointer"
              name="search"
              size="24px"
              color="primary"
              @click="searchSupplierGroup"
            />
          </template>
        </q-input>
      </div>
      <div class="row q-gutter-sm">
        <f-btn
          icon="add"
          :label="$t('new')"
          @click="addNewSupplierGroup"
        />
      </div>
    </div>

    <SupplierList :search="searchValue"></SupplierList>
  </div>

  <q-dialog v-model="display_add_dialog">
    <Create :getDisplay="DialogDisplay" :getLoading="LoadingData"></Create>
  </q-dialog>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { debounce } from 'quasar';
import Create from './Create.vue';
import SupplierList from './SupplierList.vue';

export default defineComponent({
  name: 'SupplierGroupPage',
  components: {
    Create,
    SupplierList,
  },
  data() {
    return {
      display_add_dialog: false,
      loading: false,
      searchBy: '',
      searchValue: '',
      debounceSearchFunc: null as ReturnType<typeof debounce> | null,
    };
  },
  mounted() {
    this.debounceSearchFunc = debounce(() => {
      this.searchSupplierGroup();
    }, 500);
  },
  methods: {
    addNewSupplierGroup() {
      this.display_add_dialog = true;
    },
    DialogDisplay(value: boolean) {
      this.display_add_dialog = value;
    },
    LoadingData(value: boolean) {
      this.loading = value;
    },
    updateSearchValue(value: string) {
      this.searchBy = value;
      this.debounceSearchFunc?.();
    },
    searchSupplierGroup() {
      this.searchValue = this.searchBy;
    },
  },
});
</script>
