<template>
  <q-card style="width: 600px">
    <q-form @submit="updateSupplier">
      <q-toolbar class="text-white secondary-toolbar">
        <q-toolbar-title>
          <span class="text-weight-bold">
            {{ $t('edit_supplier_group') }}
          </span>
        </q-toolbar-title>
        <q-btn flat round dense icon="close" class="text-white" v-close-popup />
      </q-toolbar>

      <q-card-section class="q-mt-md">
        <q-input
          v-model="groupApiName"
          :label="$t('group_api_name')"
          outlined
          dense
          class="col-12"
          lazy-rules
          :rules="[
            (val: any) =>
              (val && val.length > 0) || 'Please input group api name',
          ]"
        ></q-input>
        <q-input
          v-model="groupName"
          :label="$t('group_name')"
          outlined
          dense
          class="col-12 q-mt-sm"
          lazy-rules
          :rules="[
            (val: any) => (val && val.length > 0) || 'Please input group name',
          ]"
        ></q-input>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn type="submit" class="q-mr-sm" :label="$t('save')" />
      </q-card-actions>
    </q-form>
  </q-card>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, ref } from 'vue';
import { supplierGroupApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions';
import { useSupplierGroupStore } from './store/supplier.store';
import { storeToRefs } from 'pinia';
interface SupplierGroupData {
  [key: string | number]: any;
}

export default defineComponent({
  el: '#app',
    props: {
    getData: {
      type: Function,
      required: true,
    },
    getDisplay: {
      type: Function,
      required: true,
      optional: false,
    },
  },
  components: {},
  data() {
    return {
      data: {},
    };
  },
  setup() {
    const supplier_group_store = useSupplierGroupStore();
    const { getAll } = supplier_group_store;
    const { loading } = storeToRefs(supplier_group_store);

    return {
      groupApiName: ref(''),
      groupName: ref(''),
      id: ref(''),
      supplier_group_store,
      getAll,
      loading,
    };
  },
  created() {
    this.handlePopulateData();
  },
  methods: {
    handlePopulateData() {
      this.data = this.getData();
      this.groupApiName = (this.data as SupplierGroupData).group_name;
      this.groupName = (this.data as SupplierGroupData).title;
    },
    async updateSupplier() {
      try {
        this.getDisplay(false);
        this.loading = true;
        const data = {
          group_name: this.groupApiName,
          title: this.groupName,
        };
        this.id = (this.data as SupplierGroupData).id;

        const response = await supplierGroupApiService.edit(this.id, data);
        if (response.success === false) {
          notify.error(response?.message);
        } else {
          await this.supplier_group_store.getAll();
          notify.success(this.$t('supplier_group_updated_successfully'));
        }
      } catch (err: any) {
        const msg = ApiExceptions.getErrorMessage(err);
        notify.error(msg);
      } finally {
        this.loading = false;
      }
    },
  },
});
</script>
